import React from 'react';
import { Text, View, StyleSheet } from 'react-native';

const TextExample = () => {
  return (
    <View style={styles.container}>
      <Text style={styles.baseText}>
        This is base text.
        <Text style={styles.innerText}> This is nested bold text.</Text>
      </Text>

      <Text 
        numberOfLines={1} 
        ellipsizeMode='tail' 
        style={styles.longText}
      >
        This is a very long text that will be truncated after one line because of the numberOfLines prop.
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    padding: 20,
  },
  baseText: {
    fontFamily: 'Cochin',
    fontSize: 20,
    marginVertical: 10,
  },
  innerText: {
    fontWeight: 'bold',
    color: 'blue',
  },
  longText: {
    fontSize: 16,
    marginTop: 20,
    color: '#555',
  }
});

export default TextExample;
